  D.REGION = {
    luoyang: { k: N, staple: '粟', yield: 1, ill: 1, custom: ['洛阳城里的人说话带着官腔，乡下人进城，总被人笑土气。', '正月里，城中的贵人坐车出游，车马塞满了街道。', '你去看了一回太学生聚会，他们议论朝政，声音很大。'], lean: [], end: '河洛是天下的中心，也是兵家必争之地。王朝每换一次，这里就要被烧一次。' },
    guanzhong: { k: N, staple: '麦', yield: 1, ill: 1, custom: ['关中的人爱唱秦腔老调，嗓门大，性子直。', '渭水边的麦田一望无际，可田主多半是城里的豪强。', '你在长安城外看见了旧日的宫阙，只剩下残垣。'], lean: ['你家把麦麸和榆钱拌在一起蒸了吃。'], end: '关中曾是秦汉的根本。到你这一代，它已是边地和战场。' },
    yu: { k: N, staple: '粟', yield: 1, ill: 1, custom: ['颍川、汝南多名士，连乡里的农夫也爱议论人物。', '汝南的月旦评传到了乡里，人们也学着品评邻里。', '你们这里的人逢年过节要祭灶，说灶神会上天去禀报。'], lean: [], end: '颍川、汝南出了许多名士，也出了许多无名的农夫。名士的故事流传了下来，农夫的没有。' },
    yan: { k: N, staple: '粟', yield: 1, ill: 1, custom: ['兖州地势平坦，一发大水，就是一片汪洋。', '你们这里离孔子的故里不远，乡里人都敬重读书人。'], lean: ['你们沿着河滩挖野菜，河滩上挖野菜的人比野菜还多。'], end: '兖州平坦无险，是兵马来回的大道。种地的人，只能在大道两旁过日子。' },
    ji: { k: N, staple: '粟', yield: 1, ill: 1, custom: ['冀州人尚武，乡里的后生农闲时常聚在一起比试摔跤。', '河北的冬天很冷，你家把所有的被褥都盖在了身上。', '你们这里的人吃饭离不开醋和葱。'], lean: ['你家把储存的冬菜吃完了，又去刨了些去年剩在地里的萝卜。'], end: '河北是天下最富庶的地方之一，也因此最先被争夺。袁、曹两家的胜负，你家用了几十年来承受。' },
    qing: { k: N, staple: '粟', yield: 1, ill: 1, custom: ['齐地的人爱说大话，也爱读书，临淄城里有许多讲经的先生。', '海边的人家晒盐、打鱼，日子比种地的好过一点。', '你们这里有祭泰山的风俗，人们说死者的魂魄会去泰山。'], lean: ['你们去海边捡拾贝壳、海菜，煮一锅咸苦的汤。'], end: '齐鲁是儒学的故乡。可在乱世里，读过的书救不了饥荒。' },
    xu: { k: N, staple: '麦', yield: 1, ill: 1, custom: ['徐州是南北交界，北人说你们像南人，南人说你们像北人。', '下邳城里有了浮屠寺，有些人开始拜西方来的神。'], lean: [], end: '徐州在那几十年里几乎被杀空了。泗水后来又流了起来，可岸边的村子再没有回来。' },
    you: { k: N, staple: '粟', yield: 0.9, ill: 1, custom: ['幽州的冬天漫长，雪能埋到膝盖。', '你们这里多游侠，乡里的少年人人佩刀。', '塞外的乌桓人常来互市，用马匹换盐和布。'], lean: ['你家把过冬的种粮也吃了一些。'], end: '幽州苦寒，又临着塞外。汉人与胡人在这里打了几百年，也在这里通婚、互市了几百年。' },
    liaodong: { k: N, staple: '粟', yield: 0.85, ill: 1, custom: ['辽东远离中原，中原来的流民在这里开荒，说这里冬天冷得能冻掉耳朵。', '海对面就是乐浪，常有船来往。'], lean: [], end: '辽东远在天边，却收留过许多避难的中原人。他们在这里活了下来，也在这里被遗忘。' },
    bing: { k: N, staple: '粟', yield: 0.85, ill: 1, custom: ['并州多山，人们在山坡上开出一层层的田。', '你们这里汉人和匈奴人杂居，有的人家说两种话。', '并州人善骑射，连孩子都会骑马。'], lean: ['你们在山上挖了些野山药和蕨根。'], end: '并州是汉与匈奴交错的地方。你死后不到一百年，这里成了五胡的天下。' },
    liang: { k: N, staple: '麦', yield: 0.8, ill: 1, custom: ['凉州人尚武，男子人人能骑射，女子也会挽弓。', '风沙大，你家的门窗都要用泥糊严。', '河西的商队往来西域，你见过骑骆驼、高鼻深目的胡商。', '凉州羌汉杂居，邻家的媳妇就是羌人。'], lean: ['你们宰了一只老羊，熬过了最难的日子。'], end: '凉州是汉的边疆。这里的人一生都在马背上，一生都在战火里。' },
    hanzhong: { k: S, staple: '稻', yield: 1.05, ill: 1.05, custom: ['汉中山水环绕，像一个被藏起来的小天地。', '五斗米道在这里很兴盛，乡里设有义舍。'], lean: [], end: '汉中是蜀与魏之间的门户。张鲁在时，这里是乱世中的一片净土；他走后，这里成了前线。' },
    shu: { k: S, staple: '稻', yield: 1.15, ill: 1.05, custom: ['蜀中的人爱吃辛辣，说话软糯。', '成都城里织锦的机杼声昼夜不停。', '你去都江堰看了一回分水，水声震耳。', '蜀人信巫，也信道，家家户户供着神。'], lean: ['你们挖了些芋头，掺着野菜过了一个春天。'], end: '蜀中号称天府，沃野千里。可"天府"的米，大半运去了北伐的前线。' },
    nanzhong: { k: S, staple: '稻', yield: 0.95, ill: 1.25, custom: ['南中的山里住着许多部族，各说各的话，各祭各的神。', '这里的人用盐巴当钱，用竹筒盛酒。', '湿热的山谷里，瘴气一年四季不散。'], lean: ['你们进山挖了些葛根，捣成粉充饥。'], end: '南中在中原人眼里是"蛮夷之地"。可在这里，许多部族世世代代地活着，史书很少写他们的名字。' },
    jingbei: { k: S, staple: '稻', yield: 1.05, ill: 1.05, custom: ['南阳是光武皇帝的故乡，乡里人说起来都很得意。', '襄阳城里来了许多北方避乱的名士。', '荆楚之地信巫鬼，重淫祀，村头的小庙香火不断。'], lean: [], end: '荆北是南北之间的走廊。刘表在时的那十几年，是这里难得的太平。' },
    jingnan: { k: S, staple: '稻', yield: 1.15, ill: 1.15, custom: ['荆楚之地信巫鬼，每逢节日，巫觋击鼓起舞，彻夜不休。', '五月初五，江边的人划船竞渡，说是纪念投江的屈原。', '湖泽多，人们靠打鱼、采菱也能糊口。', '夏天湿热，蚊虫很多，许多人得了疟疾。'], lean: ['你们去湖里捞鱼虾、采菱角，熬过了青黄不接的日子。'], end: '荆南水泽纵横，鱼米丰饶。吴、蜀为了它打了几十年，住在这里的人只想着今年的稻子。' },
    huainan: { k: S, staple: '稻', yield: 1, ill: 1.05, custom: ['淮南是魏吴交兵之地，田地荒了大半，到处是兵营。', '淮河两岸新挖了许多沟渠，屯田的兵卒且耕且守。'], lean: [], end: '淮南在那几十年里几乎成了无人之地。"江西遂虚"，是史书留给这里的四个字。' },
    jiangdong: { k: S, staple: '稻', yield: 1.15, ill: 1.1, custom: ['吴人说话软糯，北方来的人听不懂。', '江东水网纵横，出门多半坐船。', '会稽一带的山越人断发文身，与平地的汉人少有往来。', '江南的春天多雨，屋里的衣服总是潮的。'], lean: ['你们去河塘里捞鱼虾、采莼菜，熬过了春荒。'], end: '江东在汉末还是开发未久之地。北方流民一批批南下，把这里变成了后来的鱼米之乡。' },
    jiao: { k: S, staple: '稻', yield: 1.1, ill: 1.3, custom: ['交州炎热，稻子一年能收两季。', '番禺的港口停着来自南海诸国的大船。', '这里的人嚼槟榔，牙齿染得乌黑。', '交州远离中原，北方来的士人在这里讲学著书，说这里是"世外"。'], lean: ['你们采了些野果、木薯，日子勉强过得去。'], end: '交州远在岭南，中原的战火很少烧到这里。可瘴疠和海上的风浪，一样会带走人的性命。' }
  };
  var push = function (a) { D.CHOICES.push(a); };
